import{_ as t,c as o,o as r,a5 as n}from"./chunks/framework.DuCYAsAJ.js";const h=JSON.parse('{"title":"Content RPC 服务","description":"","frontmatter":{"title":"Content RPC 服务","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#3","branch":"main","level":0,"order":3},"headers":[],"relativePath":"posts/projects/zfeed/03-content-rpc-service/index.md","filePath":"posts/projects/zfeed/03-content-rpc-service/index.md","lastUpdated":1779632679000}'),c={name:"posts/projects/zfeed/03-content-rpc-service/index.md"};function a(i,e,p,l,s,d){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="content-rpc-服务" tabindex="-1">Content RPC 服务 <a class="header-anchor" href="#content-rpc-服务" aria-label="Permalink to &quot;Content RPC 服务&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/getcontentdetaillogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/content/getcontentdetaillogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/content/content.pb.go" target="_blank" rel="noreferrer">app/rpc/content/content/content.pb.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/content/content_grpc.pb.go" target="_blank" rel="noreferrer">app/rpc/content/content/content_grpc.pb.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/etc/content.yaml" target="_blank" rel="noreferrer">app/rpc/content/etc/content.yaml</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/consts/redis/redis_consts.go" target="_blank" rel="noreferrer">app/rpc/content/internal/common/consts/redis/redis_consts.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/query_follow_inbox_zset.lua" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/query_follow_inbox_zset.lua</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/redis_lua.go" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/redis_lua.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/config/config.go" target="_blank" rel="noreferrer">app/rpc/content/internal/config/config.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/repositories/article_repository.go" target="_blank" rel="noreferrer">app/rpc/content/internal/repositories/article_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/repositories/content_repository.go" target="_blank" rel="noreferrer">app/rpc/content/internal/repositories/content_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/repositories/video_repository.go" target="_blank" rel="noreferrer">app/rpc/content/internal/repositories/video_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/server/contentserviceserver.go" target="_blank" rel="noreferrer">app/rpc/content/internal/server/contentserviceserver.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/svc/servicecontext.go" target="_blank" rel="noreferrer">app/rpc/content/internal/svc/servicecontext.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto</a></li></ul></details><p><code>content-rpc</code> 服务是负责数字内容资产（文章与视频）生命周期的核心领域服务，同时负责通过多种 Feed 机制分发这些内容，并计算全局热度排序。它充当内容相关元数据的编排器，会与 <code>user-rpc</code>、<code>interaction-rpc</code> 和 <code>count-rpc</code> 交互，为前端提供增强后的数据。</p><h2 id="服务架构" tabindex="-1">服务架构 <a class="header-anchor" href="#服务架构" aria-label="Permalink to &quot;服务架构&quot;">​</a></h2><p>该服务基于 <code>go-zero</code> 框架构建，并暴露两个主要 gRPC 服务定义：<code>ContentService</code> 负责生命周期与管理，<code>FeedService</code> 负责内容发现。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L242-L259" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#242-259</a> 它通过 <code>ServiceContext</code> 管理依赖，包括 MySQL 数据库（通过 GORM）、用于高速 Feed 缓存的 Redis，以及下游微服务客户端。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/svc/servicecontext.go#L18-L27" target="_blank" rel="noreferrer">app/rpc/content/internal/svc/servicecontext.go#18-27</a></p><h3 id="代码到系统的映射" tabindex="-1">代码到系统的映射 <a class="header-anchor" href="#代码到系统的映射" aria-label="Permalink to &quot;代码到系统的映射&quot;">​</a></h3><p>下图展示 gRPC 服务定义如何映射到其底层 logic 实现和基础设施。</p><p>Content RPC 组件图</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L242-L259" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#242-259</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/server/contentserviceserver.go#L22-L65" target="_blank" rel="noreferrer">app/rpc/content/internal/server/contentserviceserver.go#22-65</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/svc/servicecontext.go#L18-L27" target="_blank" rel="noreferrer">app/rpc/content/internal/svc/servicecontext.go#18-27</a></p><h2 id="核心子系统" tabindex="-1">核心子系统 <a class="header-anchor" href="#核心子系统" aria-label="Permalink to &quot;核心子系统&quot;">​</a></h2><h3 id="内容生命周期-发布、编辑、删除" tabindex="-1">内容生命周期：发布、编辑、删除 <a class="header-anchor" href="#内容生命周期-发布、编辑、删除" aria-label="Permalink to &quot;内容生命周期：发布、编辑、删除&quot;">​</a></h3><p>该服务使用“基础表 + 扩展表”的模式管理内容。所有内容类型共有的元数据（ID、作者、状态、可见性、计数）存储在 <code>zfeed_content</code> 中，而类型特定数据则存储在 <code>zfeed_article</code> 或 <code>zfeed_video</code> 中。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/repositories/content_repository.go#L58-L72" target="_blank" rel="noreferrer">app/rpc/content/internal/repositories/content_repository.go#58-72</a></p><p>关键操作包括：</p><ul><li>发布：同时支持文章和视频，并带有可见性控制（公开/私密）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L21-L34" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#21-34</a></li><li>分发：内容发布后，系统使用 fan-out 模型把内容推送到作者粉丝的收件箱。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L245-L246" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#245-246</a></li><li>清理：软删除逻辑会在保持引用完整性的同时，将内容从活跃 Feed 和索引中移除。</li></ul><p>详情请参阅<a href="./01-content-lifecycle-publish-edit-delete.html">内容生命周期：发布、编辑、删除</a>。</p><h3 id="内容详情聚合" tabindex="-1">内容详情聚合 <a class="header-anchor" href="#内容详情聚合" aria-label="Permalink to &quot;内容详情聚合&quot;">​</a></h3><p><code>GetContentDetail</code> 方法会聚合多个服务的数据，为单条内容提供完整视图。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L152-L180" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#152-180</a></p><ul><li>数据来源：从 MySQL 获取基础内容和类型特定详情，从 <code>user-rpc</code> 获取作者信息，从 <code>interaction-rpc</code> 获取互动状态（IsLiked、IsFavorited），并从 <code>count-rpc</code> 获取实时计数。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/svc/servicecontext.go#L42-L51" target="_blank" rel="noreferrer">app/rpc/content/internal/svc/servicecontext.go#42-51</a></li><li>查看者上下文：服务接收 <code>viewer_id</code>，用于判断当前用户是否关注作者等个性化状态。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic_test.go#L14-L52" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic_test.go#14-52</a></li></ul><p>详情请参阅<a href="./02-content-detail-aggregation.html">内容详情聚合</a>。</p><h3 id="feed-系统" tabindex="-1">Feed 系统 <a class="header-anchor" href="#feed-系统" aria-label="Permalink to &quot;Feed 系统&quot;">​</a></h3><p>该服务支持四种不同 Feed 类型，主要由 Redis Sorted Set（ZSet）驱动，以实现高性能的基于 cursor 的分页。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/consts/redis/redis_consts.go#L5-L22" target="_blank" rel="noreferrer">app/rpc/content/internal/common/consts/redis/redis_consts.go#5-22</a></p><table tabindex="0"><thead><tr><th>Feed 类型</th><th>逻辑</th><th>存储模式</th></tr></thead><tbody><tr><td>推荐</td><td>全局热门内容排序</td><td><code>feed:hot:global</code> ZSet。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/consts/redis/redis_consts.go#L6-L6" target="_blank" rel="noreferrer">app/rpc/content/internal/common/consts/redis/redis_consts.go#6</a></td></tr><tr><td>关注</td><td>面向粉丝的推模型收件箱</td><td><code>feed:follow:inbox:{uid}</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/consts/redis/redis_consts.go#L19-L19" target="_blank" rel="noreferrer">app/rpc/content/internal/common/consts/redis/redis_consts.go#19</a></td></tr><tr><td>用户发布</td><td>指定用户的时间线</td><td><code>feed:user:publish:{uid}</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/consts/redis/redis_consts.go#L15-L15" target="_blank" rel="noreferrer">app/rpc/content/internal/common/consts/redis/redis_consts.go#15</a></td></tr><tr><td>用户收藏</td><td>某用户收藏的内容</td><td><code>feed:user:favorite:{uid}</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/consts/redis/redis_consts.go#L17-L17" target="_blank" rel="noreferrer">app/rpc/content/internal/common/consts/redis/redis_consts.go#17</a></td></tr></tbody></table><p>详情请参阅<a href="./03-feed-systems-recommend-follow-user-feeds.html">Feed 系统：推荐、关注、用户 Feed</a>。</p><h3 id="热门内容排序与定时任务" tabindex="-1">热门内容排序与定时任务 <a class="header-anchor" href="#热门内容排序与定时任务" aria-label="Permalink to &quot;热门内容排序与定时任务&quot;">​</a></h3><p>推荐引擎依赖一套复杂的排序系统，将实时互动信号与时间衰减因子结合起来。</p><ul><li>排序逻辑：分数通过分片增量桶更新，以在高并发互动事件下避免 Redis 瓶颈。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/consts/redis/redis_consts.go#L9-L10" target="_blank" rel="noreferrer">app/rpc/content/internal/common/consts/redis/redis_consts.go#9-10</a></li><li>定时任务：服务集成 <code>XXL-Job</code>，运行后台任务以执行快速分数更新、快照刷新和从数据库冷重建。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/etc/content.yaml#L77-L88" target="_blank" rel="noreferrer">app/rpc/content/etc/content.yaml#77-88</a></li><li>原子操作：复杂 Feed 操作通过优化后的 Lua 脚本执行。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/redis_lua.go#L5-L37" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/redis_lua.go#5-37</a></li></ul><p>详情请参阅<a href="./04-hot-content-ranking-and-cron-jobs.html">热门内容排序与定时任务</a>。</p><h2 id="交互流程" tabindex="-1">交互流程 <a class="header-anchor" href="#交互流程" aria-label="Permalink to &quot;交互流程&quot;">​</a></h2><p>下图展示 <code>content-rpc</code> 在内容获取请求中如何与其他服务交互。</p><p>GetContentDetail 交互序列</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic_test.go#L45-L71" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic_test.go#45-71</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/svc/servicecontext.go#L35-L41" target="_blank" rel="noreferrer">app/rpc/content/internal/svc/servicecontext.go#35-41</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/getcontentdetaillogic_test.go#L14-L39" target="_blank" rel="noreferrer">app/front/internal/logic/content/getcontentdetaillogic_test.go#14-39</a></p>',31)])])}const g=t(c,[["render",a]]);export{h as __pageData,g as default};
